SELECT COUNT(*) as total_top_tier FROM productbatches 
WHERE tempsense = 'High' 
AND CAST(REPLACE(REPLACE(valusd, '$', ''), ',', '') AS numeric) > 100000;

SELECT COUNT(*) as top_tier_count FROM productbatches 
WHERE tempsense = 'High' 
AND CAST(REPLACE(REPLACE(valusd, '$', ''), ',', '') AS numeric) > 100000;

WITH total AS (SELECT COUNT(*) AS cnt FROM productbatches),
tier1_count AS (SELECT COUNT(*) AS cnt FROM productbatches WHERE valusd LIKE '%[TIER1]%')
SELECT ROUND(CAST(t.cnt AS numeric) * 100 / p.cnt, 2) AS tier1_percentage FROM tier1_count t, total p;
